-- Votos de LEGENDA 2026 por partido e municipio (par.tval dos arquivos de
-- totalizacao do TSE, 1o turno, Dep Federal/Estadual). Com isso a pagina
-- Quociente e Simulacoes mostra 2026 com nominais + legenda destacados,
-- a composicao das cadeiras (QE + sobras) e o PDF do relatorio.

DELETE FROM VotoLegenda WHERE cargoId IN (SELECT c.id FROM Cargo c JOIN Eleicao e ON c.eleicaoId = e.id WHERE e.ano = 2026);

CREATE TEMP TABLE tmp_leg26 (cargo TEXT, slug TEXT, nr INTEGER, sigla TEXT, cod TEXT, votos INTEGER);
