INSERT INTO VotoLegenda (id, cargoId, municipioId, partidoId, turno, votos)
SELECT 'vl26-' || t.slug || '-' || t.nr || '-' || t.cod,
  (SELECT c.id FROM Cargo c JOIN Eleicao e ON c.eleicaoId = e.id WHERE e.ano = 2026 AND c.nome = t.cargo),
  m.id,
  (SELECT MIN(p.id) FROM Partido p WHERE UPPER(REPLACE(p.sigla, ' ', '')) = UPPER(REPLACE(t.sigla, ' ', ''))),
  1, t.votos
FROM tmp_leg26 t
JOIN Municipio m ON m.codigoTse = t.cod
WHERE EXISTS (SELECT 1 FROM Partido p WHERE UPPER(REPLACE(p.sigla, ' ', '')) = UPPER(REPLACE(t.sigla, ' ', '')));

DROP TABLE tmp_leg26;
